import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { PersistenceService } from '../src/services/persistence-service';

/** A PersistenceService over a fresh temp directory. Call cleanup() in afterEach. */
export function tempPersistence() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-test-'));
  const dataDir = path.join(dir, 'knowledge-base-data');
  return {
    dataDir,
    persistence: new PersistenceService(dataDir),
    cleanup: () => fs.rmSync(dir, { recursive: true, force: true }),
  };
}

export const SAMPLE_DOCS = path.resolve(__dirname, '..', 'data', 'sample-documents');

/** Minimal stand-in for Electron's ipcMain that records handlers so tests can invoke them. */
export function fakeIpcMain() {
  const handlers = new Map<string, (event: unknown, ...args: unknown[]) => unknown>();
  return {
    handlers,
    handle(channel: string, fn: (event: unknown, ...args: unknown[]) => unknown) {
      handlers.set(channel, fn);
    },
    invoke(channel: string, ...args: unknown[]) {
      const fn = handlers.get(channel);
      if (!fn) throw new Error(`No handler for ${channel}`);
      return Promise.resolve(fn({}, ...args));
    },
  };
}
