// E2E for answer feedback: ids on answers, UI buttons, bridge API, persistence across restart.
// Usage: npm run build && node --experimental-websocket scripts/e2e/feedback.mjs
import * as fs from 'node:fs';
import { launch, tempDataDir, importSamples, askViaUi, DOM, check, finish } from './cdp.mjs';

const dataDir = tempDataDir();
try {
  let app = await launch(dataDir);
  check('samples imported', (await importSamples(app)) === 3);

  // Bridge: ask returns unique string ids
  const ids = await app.evaluate(`(async () => {
    const a = await window.knowledgeBase.qa.ask('What does the design say about architecture?');
    const b = await window.knowledgeBase.qa.ask('What does the design say about architecture?');
    return [a.id, b.id];
  })()`);
  check('qa.ask returns string ids', ids.every((id) => typeof id === 'string' && id.length > 0), ids);
  check('ids are unique', ids[0] !== ids[1]);

  // UI: ask, then rate the shown answer as helpful
  await askViaUi(app, 'How does indexing split documents into chunks?');
  await app.waitFor(`document.querySelectorAll('[aria-label="Mark answer helpful"]').length > 0`, 'feedback buttons');
  const uiAnswerId = await app.evaluate(`(() => { ${DOM}
    const btns = $label('Mark answer helpful');
    const btn = btns[btns.length - 1];
    btn.click();
    return btn.closest('[data-answer-id]').dataset.answerId;
  })()`);
  check('both buttons present', await app.evaluate(`(() => { ${DOM} return $label('Mark answer helpful').length > 0 && $label('Mark answer not helpful').length > 0; })()`));
  await app.waitFor(`document.querySelector('[data-answer-id="${uiAnswerId}"] [aria-label="Mark answer helpful"]').getAttribute('aria-pressed') === 'true'`, 'helpful pressed');
  check('UI click marks helpful as pressed', true);

  // Bridge: submit for one answer, list
  await app.evaluate(`window.knowledgeBase.feedback.submit(${JSON.stringify(ids[0])}, 'down')`);
  const invalid = await app.evaluate(`window.knowledgeBase.feedback.submit('x', 'meh').then(() => 'accepted', (e) => 'rejected')`);
  check('invalid rating rejected', invalid === 'rejected', invalid);
  const before = await app.evaluate(`window.knowledgeBase.feedback.list()`);
  check('list has UI rating', before.some((e) => e.answerId === uiAnswerId && e.rating === 'up'), before);
  check('list has bridge rating', before.some((e) => e.answerId === ids[0] && e.rating === 'down'));
  check('entries have shape {answerId, rating, timestamp}', before.every((e) =>
    Object.keys(e).sort().join() === 'answerId,rating,timestamp' && !isNaN(Date.parse(e.timestamp))));
  await app.close();

  // Restart on the same data dir
  app = await launch(dataDir);
  const after = await app.evaluate(`window.knowledgeBase.feedback.list()`);
  check('ratings persist across restart', JSON.stringify(after) === JSON.stringify(before), after);
  // Ratings are reflected in the UI after restart (history view, if behind a toggle)
  await app.evaluate(`(() => { ${DOM} const b = $text('button', 'Show History')[0]; if (b) b.click(); })()`);
  await app.waitFor(`document.querySelector('[data-answer-id="${uiAnswerId}"] [aria-label="Mark answer helpful"]')?.getAttribute('aria-pressed') === 'true'`, 'rating shown after restart');
  check('rating shown in UI after restart', true);
  await app.close();
} catch (err) {
  check('scenario ran without errors', false, String(err));
} finally {
  fs.rmSync(dataDir, { recursive: true, force: true });
}
finish();
EOF
