// Small driver for end-to-end checks: launches the real Electron app with an isolated
// user data dir, talks to the window over Chrome DevTools, and can restart the app on
// the same data dir to check persistence. Requires a prior `npm run build`.
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
export const SAMPLES = path.join(ROOT, 'data', 'sample-documents');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export function tempDataDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'kb-e2e-'));
}

export async function launch(dataDir, port = 9360) {
  const env = { ...process.env };
  delete env.NODE_OPTIONS; // this shell's NODE_OPTIONS breaks Electron
  const proc = spawn(require('electron'), ['.', `--remote-debugging-port=${port}`, `--user-data-dir=${dataDir}`], {
    cwd: ROOT, env, stdio: 'ignore',
  });
  const exited = new Promise((r) => proc.once('exit', r));

  let page;
  for (let i = 0; i < 60 && !page; i++) {
    try {
      const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
      page = targets.find((t) => t.type === 'page');
    } catch { /* not up yet */ }
    if (!page) await sleep(500);
  }
  if (!page) { proc.kill(); throw new Error('Electron window did not appear'); }

  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((r, j) => { ws.addEventListener('open', r); ws.addEventListener('error', j); });
  let nextId = 1;
  const pending = new Map();
  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  });
  const send = (method, params) => new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, resolve);
    ws.send(JSON.stringify({ id, method, params }));
  });

  /** Evaluate an expression in the page (promises are awaited). Throws on page errors. */
  async function evaluate(expression) {
    const msg = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (msg.result?.exceptionDetails) {
      throw new Error(`Page error: ${msg.result.exceptionDetails.exception?.description ?? msg.result.exceptionDetails.text}`);
    }
    return msg.result?.result?.value;
  }

  /** Poll a boolean expression until it is true. */
  async function waitFor(expression, label, timeoutMs = 10000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      if (await evaluate(`(() => { try { return !!(${expression}); } catch { return false; } })()`)) return;
      await sleep(100);
    }
    throw new Error(`Timed out waiting for: ${label ?? expression}`);
  }

  await waitFor(`typeof window.knowledgeBase === 'object' && document.querySelector('#root')?.children.length > 0`, 'app ready');
  await sleep(300); // let the initial loads settle

  async function close() {
    ws.close();
    proc.kill('SIGTERM');
    await Promise.race([exited, sleep(5000)]);
  }

  return { evaluate, waitFor, close };
}

/** In-page helpers, injected as a string prefix for evaluate(). */
export const DOM = `
  const $label = (l) => Array.from(document.querySelectorAll('[aria-label="' + l + '"]'));
  const $text = (sel, t) => Array.from(document.querySelectorAll(sel)).filter((e) => e.textContent.trim() === t);
  const setInput = (el, value) => {
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
    setter.call(el, value);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  };
`;

/** Type a question in the UI and press Ask. */
export async function askViaUi(app, question) {
  await app.evaluate(`(() => { ${DOM}
    const input = document.querySelector('input[placeholder^="Ask a question"]');
    setInput(input, ${JSON.stringify(question)});
    $text('button', 'Ask')[0].click();
  })()`);
}

/** Import and index every sample document through the bridge. */
export async function importSamples(app) {
  const files = fs.readdirSync(SAMPLES).map((f) => path.join(SAMPLES, f));
  return app.evaluate(`(async () => {
    for (const f of ${JSON.stringify(files)}) await window.knowledgeBase.documents.import(f);
    await window.knowledgeBase.indexing.start();
    return (await window.knowledgeBase.documents.list()).length;
  })()`);
}

let failures = 0;
export function check(name, ok, detail) {
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'}: ${name}${detail !== undefined ? ` -> ${JSON.stringify(detail)}` : ''}`);
}
export function finish() {
  console.log(failures === 0 ? 'E2E OK' : `E2E FAILED (${failures})`);
  process.exit(failures === 0 ? 0 : 1);
}
EOF
