import { useState } from 'react';

interface Props {
  onReset: () => Promise<void>;
}

/** Header button that asks for confirmation, then deletes all app data. */
export function ResetDataButton({ onReset }: Props) {
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const confirm = async () => {
    setBusy(true);
    setError(null);
    try {
      await onReset();
      setConfirming(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <button
        type="button"
        aria-label="Reset all data"
        onClick={() => { setError(null); setConfirming(true); }}
        style={{
          padding: '6px 14px',
          background: '#5c1f1d',
          color: '#f0d0d0',
          border: '1px solid #8b2f2b',
          borderRadius: '4px',
          cursor: 'pointer',
          fontSize: '13px',
        }}
      >
        Reset
      </button>
      {confirming && (
        <div
          style={{
            position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 10,
          }}
        >
          <div
            role="alertdialog"
            aria-modal="true"
            aria-labelledby="reset-title"
            aria-describedby="reset-desc"
            style={{
              background: '#16213e', border: '1px solid #8b2f2b', borderRadius: '6px',
              padding: '20px', maxWidth: '420px',
            }}
          >
            <h2 id="reset-title" style={{ fontSize: '16px', marginBottom: '8px' }}>Reset all data?</h2>
            <p id="reset-desc" style={{ fontSize: '13px', color: '#c0c0d0', lineHeight: 1.5 }}>
              This permanently deletes all documents, chunks, Q&amp;A history and feedback. This cannot be undone.
            </p>
            {error && (
              <p role="alert" style={{ fontSize: '12px', color: '#ff8a80', marginTop: '8px' }}>Reset failed: {error}</p>
            )}
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px', marginTop: '16px' }}>
              <button
                type="button"
                autoFocus
                disabled={busy}
                onClick={() => setConfirming(false)}
                style={{
                  padding: '6px 14px', background: '#0f3460', color: '#e0e0e0',
                  border: '1px solid #1a1a4e', borderRadius: '4px', cursor: 'pointer', fontSize: '13px',
                }}
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={busy}
                onClick={confirm}
                style={{
                  padding: '6px 14px', background: '#b23b37', color: '#fff',
                  border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '13px',
                }}
              >
                {busy ? 'Resetting…' : 'Yes, delete everything'}
              </button>
