import * as fs from 'fs';
import * as path from 'path';
import { afterEach, describe, expect, it } from 'vitest';
import { registerIpcHandlers, Services } from '../src/main/ipc-handlers';
import { DocumentService } from '../src/services/document-service';
import { FeedbackService } from '../src/services/feedback-service';
import { IndexingService } from '../src/services/indexing-service';
import { PersistenceService } from '../src/services/persistence-service';
import { QaService } from '../src/services/qa-service';
import { IPC_CHANNELS } from '../src/shared/types';
import { fakeIpcMain, SAMPLE_DOCS, tempPersistence } from './helpers';

let cleanup: () => void = () => {};
afterEach(() => cleanup());

function wire(persistence: PersistenceService) {
  const indexingService = new IndexingService(persistence);
  const services: Services = {
    documentService: new DocumentService(persistence),
    indexingService,
    qaService: new QaService(persistence, indexingService),
    feedbackService: new FeedbackService(persistence),
    persistence,
  };
  const ipc = fakeIpcMain();
  registerIpcHandlers(ipc as never, services);
  return { ipc, services };
}

async function populate(ipc: ReturnType<typeof fakeIpcMain>) {
  for (const f of fs.readdirSync(SAMPLE_DOCS)) {
    await ipc.invoke(IPC_CHANNELS.IMPORT_DOCUMENT, path.join(SAMPLE_DOCS, f));
  }
  await ipc.invoke(IPC_CHANNELS.START_INDEXING);
  const answer = (await ipc.invoke(IPC_CHANNELS.ASK_QUESTION, 'how does retrieval work?')) as { id: string };
  await ipc.invoke(IPC_CHANNELS.SUBMIT_FEEDBACK, answer.id, 'up');
}

describe('app:reset', () => {
  it('deletes documents, chunks, Q&A history and feedback', async () => {
    const t = tempPersistence();
    cleanup = t.cleanup;
    const { ipc, services } = wire(t.persistence);
    await populate(ipc);
    expect(services.documentService.listDocuments()).toHaveLength(3);
    expect(services.indexingService.getAllChunks().length).toBeGreaterThan(0);
    expect(services.qaService.getHistory()).toHaveLength(1);
    expect(services.feedbackService.list()).toHaveLength(1);

    await ipc.invoke(IPC_CHANNELS.RESET_APP);

    expect(await ipc.invoke(IPC_CHANNELS.LIST_DOCUMENTS)).toEqual([]);
    expect(services.indexingService.getAllChunks()).toEqual([]);
    expect(await ipc.invoke(IPC_CHANNELS.GET_HISTORY)).toEqual([]);
    expect(await ipc.invoke(IPC_CHANNELS.LIST_FEEDBACK)).toEqual([]);
    expect(await ipc.invoke(IPC_CHANNELS.GET_INDEXING_STATUS)).toMatchObject({ currentIndexed: 0, totalDocuments: 0 });
    // Nothing from before survives on disk except the empty directory skeleton
    expect(t.persistence.listFiles('content')).toEqual([]);
    expect(t.persistence.listFiles('chunks')).toEqual([]);
    expect(t.persistence.listFiles('documents')).toEqual([]);
  });

  it('stays empty after a restart and the app keeps working afterwards', async () => {
    const t = tempPersistence();
    cleanup = t.cleanup;
    const first = wire(t.persistence);
    await populate(first.ipc);
    await first.ipc.invoke(IPC_CHANNELS.RESET_APP);

    // "Restart": fresh services over the same data dir
    const second = wire(new PersistenceService(t.dataDir));
    expect(await second.ipc.invoke(IPC_CHANNELS.LIST_DOCUMENTS)).toEqual([]);
    expect(await second.ipc.invoke(IPC_CHANNELS.GET_HISTORY)).toEqual([]);
    expect(await second.ipc.invoke(IPC_CHANNELS.LIST_FEEDBACK)).toEqual([]);

    await populate(second.ipc);
    expect(await second.ipc.invoke(IPC_CHANNELS.LIST_DOCUMENTS)).toHaveLength(3);
  });
});
EOF
