cat > scripts/e2e/reset.mjs <<'EOF'
// E2E for reset: confirmation dialog (cancel keeps data, confirm deletes it), UI returns
// to empty, bridge app.reset(), and the empty state survives a restart.
// Usage: npm run build && node --experimental-websocket scripts/e2e/reset.mjs
import * as fs from 'node:fs';
import { launch, tempDataDir, importSamples, askViaUi, DOM, check, finish } from './cdp.mjs';

const counts = `(async () => {
  const kb = window.knowledgeBase;
  const docs = await kb.documents.list();
  let chunks = 0;
  for (const d of docs) chunks += (await kb.indexing.chunks(d.id)).length;
  return { docs: docs.length, chunks, history: (await kb.qa.history()).length, feedback: (await kb.feedback.list()).length };
})()`;

async function populate(app) {
  await importSamples(app);
  await app.evaluate(`window.knowledgeBase.qa.ask('what is the architecture?').then((a) => window.knowledgeBase.feedback.submit(a.id, 'up'))`);
  await app.evaluate(`window.dispatchEvent(new Event('focus'))`);
}

const dataDir = tempDataDir();
try {
  let app = await launch(dataDir);
  await populate(app);
  await askViaUi(app, 'how does indexing work?');
  await app.waitFor(`document.querySelectorAll('[aria-label="Mark answer helpful"]').length > 0`, 'answer shown');
  // Refresh so the sidebar lists the imported docs
  await app.evaluate(`(() => { ${DOM} $text('button', 'Refresh')[0].click(); })()`);
  await app.waitFor(`document.body.innerText.includes('Documents (3)')`, 'sidebar shows 3 docs');
  const full = await app.evaluate(counts);
  check('populated', full.docs === 3 && full.chunks > 0 && full.history === 2 && full.feedback === 1, full);

  // Reset button asks for confirmation; Cancel keeps everything
  await app.evaluate(`(() => { ${DOM} $label('Reset all data')[0].click(); })()`);
  await app.waitFor(`document.querySelector('[role="alertdialog"]')`, 'confirmation dialog');
  check('confirmation dialog shown', true, await app.evaluate(`document.querySelector('[role="alertdialog"]').innerText`));
  check('nothing deleted before confirming', JSON.stringify(await app.evaluate(counts)) === JSON.stringify(full));
  await app.evaluate(`(() => { ${DOM} $text('button', 'Cancel')[0].click(); })()`);
  await app.waitFor(`!document.querySelector('[role="alertdialog"]')`, 'dialog closed');
  check('cancel keeps data', JSON.stringify(await app.evaluate(counts)) === JSON.stringify(full));

  // Confirm deletes everything and the UI returns to empty
  await app.evaluate(`(() => { ${DOM} $label('Reset all data')[0].click(); })()`);
  await app.waitFor(`document.querySelector('[role="alertdialog"]')`, 'confirmation dialog again');
  await app.evaluate(`(() => { ${DOM} $text('button', 'Yes, delete everything')[0].click(); })()`);
  await app.waitFor(`!document.querySelector('[role="alertdialog"]') && document.body.innerText.includes('Documents (0)')`, 'UI empty');
  const empty = await app.evaluate(counts);
  check('confirm deletes docs, chunks, history, feedback', empty.docs === 0 && empty.chunks === 0 && empty.history === 0 && empty.feedback === 0, empty);
  check('UI shows empty state', await app.evaluate(`document.body.innerText.includes('No documents imported yet') && document.querySelectorAll('[aria-label="Mark answer helpful"]').length === 0`));
  await app.close();

  // Restart: still empty
  app = await launch(dataDir);
  const afterRestart = await app.evaluate(counts);
  check('empty state persists after restart', afterRestart.docs === 0 && afterRestart.history === 0 && afterRestart.feedback === 0, afterRestart);
  check('UI empty after restart', await app.evaluate(`document.body.innerText.includes('Documents (0)')`));

  // Bridge reset works directly too, and the app is usable afterwards
  await populate(app);
  await app.evaluate(`window.knowledgeBase.app.reset()`);
  const viaBridge = await app.evaluate(counts);
  check('window.knowledgeBase.app.reset() empties everything', viaBridge.docs === 0 && viaBridge.history === 0 && viaBridge.feedback === 0, viaBridge);
  check('app usable after reset', (await importSamples(app)) === 3);
  await app.close();
} catch (err) {
  check('scenario ran without errors', false, String(err));
} finally {
  fs.rmSync(dataDir, { recursive: true, force: true });
}
finish();
EOF
