interface Props {
  value: number;
}

export function confidenceLevel(value: number): 'high' | 'medium' | 'low' {
  if (value >= 0.7) return 'high';
  if (value >= 0.4) return 'medium';
  return 'low';
}

const COLORS = { high: '#5cb85c', medium: '#f0ad4e', low: '#d9534f' } as const;
const LABELS = { high: 'High', medium: 'Medium', low: 'Low' } as const;

/** Color-coded confidence bar with a text label, so it does not rely on color alone. */
export function ConfidenceIndicator({ value }: Props) {
  const clamped = Math.max(0, Math.min(1, value));
  const pct = Math.round(clamped * 100);
  const level = confidenceLevel(clamped);
  return (
    <span
      role="meter"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={pct}
      aria-label={`Confidence ${pct}% (${level})`}
      data-confidence-level={level}
      style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '11px', color: '#a0a0c0' }}
    >
      <span style={{ width: '48px', height: '6px', background: '#0f3460', borderRadius: '3px', overflow: 'hidden' }}>
        <span style={{ display: 'block', width: `${pct}%`, height: '100%', background: COLORS[level] }} />
      </span>
      <span style={{ color: COLORS[level] }}>{LABELS[level]} confidence</span>
      <span>{pct}%</span>
    </span>
  );
}
