import { useEffect, useRef } from 'react';
import { QAHistory, FeedbackRating, Citation } from '../../shared/types';
import { AnswerFeedback } from './AnswerFeedback';
import { ConfidenceIndicator } from './ConfidenceIndicator';

interface Props {
  history: QAHistory[];
  /** Question currently waiting for an answer, shown at the end of the conversation. */
  pendingQuestion: string | null;
  error: string | null;
  ratings: Record<string, FeedbackRating>;
  onRate: (answerId: string, rating: FeedbackRating) => void;
}

const bubble = {
  padding: '10px 14px',
  borderRadius: '10px',
  fontSize: '13px',
  lineHeight: 1.55,
  maxWidth: '80%',
  whiteSpace: 'pre-wrap' as const,
};

function QuestionBubble({ text }: { text: string }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
      <div data-role="question" style={{ ...bubble, background: '#533483', color: '#fff', borderBottomRightRadius: '2px' }}>
        {text}
      </div>
    </div>
  );
}

function Citations({ citations }: { citations: Citation[] }) {
  if (citations.length === 0) {
    return <div style={{ fontSize: '11px', color: '#777', marginTop: '8px' }}>No citations: no indexed passage matched this question.</div>;
  }
  return (
    <div style={{ marginTop: '8px' }} aria-label="Citations">
      <div style={{ fontSize: '11px', color: '#8888bb', marginBottom: '4px' }}>Citations ({citations.length})</div>
      {citations.map((c, i) => (
        <details key={i} data-role="citation" style={{ fontSize: '12px', marginTop: '4px' }}>
          <summary style={{ cursor: 'pointer', color: '#b0b0e0' }}>
            [{i + 1}] {c.documentTitle} · chunk {c.chunkIndex}
          </summary>
          <blockquote
            data-role="excerpt"
            style={{
              margin: '6px 0 2px 12px', paddingLeft: '8px', borderLeft: '2px solid #533483',
              color: '#c8c8e0', whiteSpace: 'pre-wrap', lineHeight: 1.5,
            }}
          >
            {c.excerpt}
          </blockquote>
        </details>
      ))}
    </div>
  );
}

/** The full Q&A history as a chat: questions on the right, answers on the left. */
export function ConversationHistory({ history, pendingQuestion, error, ratings, onRate }: Props) {
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView?.({ block: 'end' });
  }, [history.length, pendingQuestion, error]);

  if (history.length === 0 && !pendingQuestion && !error) {
    return (
      <div style={{ color: '#666', textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
        No questions yet. Ask something about your documents to start a conversation.
      </div>
    );
  }

  return (
    <div role="log" aria-label="Conversation" style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      {history.map(item => (
        <div key={item.response.id} data-role="exchange" style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <QuestionBubble text={item.question} />
          <div style={{ display: 'flex', justifyContent: 'flex-start' }}>
            <div
              data-role="answer"
              data-answer-id={item.response.id}
              style={{ ...bubble, background: '#1a1a3e', border: '1px solid #0f3460', borderBottomLeftRadius: '2px' }}
            >
              <div>{item.response.answer}</div>
              <Citations citations={item.response.citations} />
              <div style={{ marginTop: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
                <ConfidenceIndicator value={item.response.confidence} />
                <span style={{ fontSize: '10px', color: '#666' }}>
                  {new Date(item.response.timestamp).toLocaleString()}
                </span>
                <AnswerFeedback answerId={item.response.id} rating={ratings[item.response.id]} onRate={onRate} />
              </div>
            </div>
          </div>
        </div>
      ))}
      {pendingQuestion && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <QuestionBubble text={pendingQuestion} />
          <div aria-live="polite" style={{ ...bubble, background: '#1a1a3e', color: '#888', alignSelf: 'flex-start' }}>
            Thinking…
          </div>
        </div>
      )}
      {error && (
        <div role="alert" style={{ ...bubble, background: '#3a1a1a', color: '#ff8a80', alignSelf: 'flex-start' }}>
          {error}
        </div>
      )}
      <div ref={endRef} />
    </div>
  );
}
EOF
cat > src/renderer/components/QuestionPanel.tsx <<'EOF'
import React, { useState } from 'react';
import { QAHistory, FeedbackRating } from '../../shared/types';
import { ConversationHistory } from './ConversationHistory';

interface Props {
  history: QAHistory[];
  pendingQuestion: string | null;
  error: string | null;
  ratings: Record<string, FeedbackRating>;
  onAsk: (question: string) => void;
  onRate: (answerId: string, rating: FeedbackRating) => void;
  onClearHistory: () => void;
}

/** Conversation with the knowledge base: full Q&A history plus the question input. */
export function QuestionPanel({ history, pendingQuestion, error, ratings, onAsk, onRate, onClearHistory }: Props) {
  const [question, setQuestion] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim() || pendingQuestion) return;
    onAsk(question.trim());
    setQuestion('');
  };

  return (
    <section aria-label="Questions" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div style={{
        padding: '8px 20px', borderBottom: '1px solid #0f3460',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
      }}>
        <h3 style={{ fontSize: '14px', fontWeight: 600 }}>Conversation ({history.length})</h3>
        {history.length > 0 && (
          <button
            type="button"
            onClick={onClearHistory}
            disabled={!!pendingQuestion}
            style={{
              padding: '3px 10px', background: 'transparent', color: '#d9534f',
              border: '1px solid #d9534f', borderRadius: '3px', cursor: 'pointer', fontSize: '12px',
            }}
          >
            Clear history
          </button>
        )}
      </div>
      <div style={{ flex: 1, overflow: 'auto', padding: '16px 20px' }}>
        <ConversationHistory
          history={history}
          pendingQuestion={pendingQuestion}
          error={error}
          ratings={ratings}
          onRate={onRate}
        />
      </div>
      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        <input
          type="text"
          value={question}
          onChange={e => setQuestion(e.target.value)}
          placeholder="Ask a question about your documents..."
          aria-label="Question"
          style={{
            flex: 1,
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            outline: 'none',
          }}
        />
        <button
          type="submit"
          disabled={!!pendingQuestion}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: pendingQuestion ? 'wait' : 'pointer',
            fontSize: '14px',
            fontWeight: 500,
            opacity: pendingQuestion ? 0.6 : 1,
          }}
        >
          Ask
        </button>
      </form>
    </section>
  );
}
EOF

