import * as fs from 'fs';
import * as path from 'path';
import { renderToStaticMarkup } from 'react-dom/server';
import { afterEach, describe, expect, it } from 'vitest';
import { ConversationHistory } from '../src/renderer/components/ConversationHistory';
import { ConfidenceIndicator, confidenceLevel } from '../src/renderer/components/ConfidenceIndicator';
import { DocumentService } from '../src/services/document-service';
import { IndexingService } from '../src/services/indexing-service';
import { QaService } from '../src/services/qa-service';
import { QAHistory } from '../src/shared/types';
import { SAMPLE_DOCS, tempPersistence } from './helpers';

let cleanup: () => void = () => {};
afterEach(() => cleanup());

const noop = () => {};

const HISTORY: QAHistory[] = [
  {
    question: 'How is retrieval done?',
    response: {
      id: 'a1',
      answer: 'Retrieval matches keywords.',
      citations: [
        { documentId: 'd1', documentTitle: 'retrieval-plan', chunkIndex: 2, excerpt: 'Chunks are ranked by keyword overlap.' },
        { documentId: 'd2', documentTitle: 'design-notes', chunkIndex: 0, excerpt: 'Layered architecture & IPC.' },
      ],
      confidence: 0.85,
      timestamp: '2026-11-15T10:00:00.000Z',
    },
  },
  {
    question: 'What about the weather?',
    response: { id: 'a2', answer: 'No relevant documents.', citations: [], confidence: 0.3, timestamp: '2026-11-15T10:01:00.000Z' },
  },
];

describe('ConversationHistory', () => {
  const html = renderToStaticMarkup(
    <ConversationHistory history={HISTORY} pendingQuestion={null} error={null} ratings={{ a1: 'up' }} onRate={noop} />
  );

  it('shows every question and answer in order', () => {
    const order = ['How is retrieval done?', 'Retrieval matches keywords.', 'What about the weather?', 'No relevant documents.'];
    const positions = order.map(t => html.indexOf(t));
    expect(positions.every(p => p >= 0)).toBe(true);
    expect([...positions].sort((a, b) => a - b)).toEqual(positions);
    expect(html.match(/data-role="answer"/g)).toHaveLength(2);
  });

  it('renders each citation as a collapsed <details> holding the excerpt', () => {
    expect(html.match(/<details data-role="citation"/g)).toHaveLength(2);
    expect(html).not.toMatch(/<details[^>]* open/);
    expect(html).toContain('retrieval-plan · chunk 2');
    expect(html).toMatch(/<blockquote data-role="excerpt"[^>]*>Chunks are ranked by keyword overlap\.<\/blockquote>/);
    expect(html).toContain('Layered architecture &amp; IPC.');
    expect(html).toContain('No citations');
  });

  it('shows a confidence indicator per answer', () => {
    expect(html).toContain('aria-label="Confidence 85% (high)"');
    expect(html).toContain('aria-label="Confidence 30% (low)"');
  });

  it('shows feedback buttons per answer with the saved rating pressed', () => {
    expect(html.match(/aria-label="Mark answer helpful"/g)).toHaveLength(2);
    expect(html.match(/aria-label="Mark answer not helpful"/g)).toHaveLength(2);
    expect(html).toMatch(/data-answer-id="a1"[\s\S]*aria-label="Mark answer helpful" aria-pressed="true"/);
  });

  it('shows the pending question and errors', () => {
    const pending = renderToStaticMarkup(
      <ConversationHistory history={[]} pendingQuestion="Still thinking?" error="boom" ratings={{}} onRate={noop} />
    );
    expect(pending).toContain('Still thinking?');
    expect(pending).toContain('Thinking…');
    expect(pending).toContain('role="alert"');
  });

  it('shows an empty state with no history', () => {
    const empty = renderToStaticMarkup(
      <ConversationHistory history={[]} pendingQuestion={null} error={null} ratings={{}} onRate={noop} />
    );
    expect(empty).toContain('No questions yet');
  });
});

describe('ConfidenceIndicator', () => {
  it('maps confidence to levels', () => {
    expect(confidenceLevel(0.85)).toBe('high');
    expect(confidenceLevel(0.5)).toBe('medium');
    expect(confidenceLevel(0.3)).toBe('low');
  });
  it('clamps out-of-range values', () => {
    expect(renderToStaticMarkup(<ConfidenceIndicator value={1.7} />)).toContain('aria-valuenow="100"');
  });
});

describe('Q&A history feeds the conversation', () => {
  it('keeps every exchange in order with citations, excerpts and confidence', async () => {
    const t = tempPersistence();
    cleanup = t.cleanup;
    const docs = new DocumentService(t.persistence);
    for (const f of fs.readdirSync(SAMPLE_DOCS)) docs.importDocument(path.join(SAMPLE_DOCS, f));
    const indexing = new IndexingService(t.persistence);
    await indexing.startIndexing();
    const qa = new QaService(t.persistence, indexing);

    await qa.ask('How does retrieval rank chunks?');
    await qa.ask('zzzz qqqq');
    const history = qa.getHistory();
    expect(history.map(h => h.question)).toEqual(['How does retrieval rank chunks?', 'zzzz qqqq']);
    expect(history[0].response.citations.length).toBeGreaterThan(0);
    expect(history[0].response.citations[0].excerpt.length).toBeGreaterThan(0);
    expect(history[0].response.confidence).toBeGreaterThan(history[1].response.confidence);
  });
});
EOF
