// E2E for the conversation view in the question panel: full history in order, citations
// that expand to show the excerpt, a confidence indicator per answer, history after restart.
// Usage: npm run build && node --experimental-websocket scripts/e2e/conversation.mjs [screenshot-dir]
import * as fs from 'node:fs';
import * as path from 'node:path';
import { launch, tempDataDir, importSamples, askViaUi, DOM, check, finish } from './cdp.mjs';

const shotDir = process.argv[2];
const QUESTIONS = [
  'How does retrieval rank the chunks?',
  'What did the meeting decide?',
  'zzzz qqqq nothing matches',
];
const panel = `document.querySelector('section[aria-label="Questions"]')`;
const readConversation = `(() => Array.from(${panel}.querySelectorAll('[data-role="exchange"]')).map((ex) => ({
  question: ex.querySelector('[data-role="question"]').innerText,
  answerId: ex.querySelector('[data-role="answer"]').dataset.answerId,
  citations: ex.querySelectorAll('[data-role="citation"]').length,
  confidence: Number(ex.querySelector('[role="meter"]')?.getAttribute('aria-valuenow')),
  helpful: !!ex.querySelector('[aria-label="Mark answer helpful"]'),
})))()`;

const dataDir = tempDataDir();
try {
  let app = await launch(dataDir);
  check('empty conversation state', await app.evaluate(`${panel}.innerText.includes('No questions yet')`));
  await importSamples(app);

  for (const [i, q] of QUESTIONS.entries()) {
    await askViaUi(app, q);
    await app.waitFor(`${panel}.querySelectorAll('[data-role="exchange"]').length === ${i + 1}`, `answer ${i + 1}`);
  }
  const conv = await app.evaluate(readConversation);
  const history = await app.evaluate(`window.knowledgeBase.qa.history()`);
  check('panel shows every exchange in order', JSON.stringify(conv.map((c) => c.question)) === JSON.stringify(QUESTIONS), conv.map((c) => c.question));
  check('answers match persisted history', JSON.stringify(conv.map((c) => c.answerId)) === JSON.stringify(history.map((h) => h.response.id)));
  check('citations rendered per answer', conv.every((c, i) => c.citations === history[i].response.citations.length) && conv[0].citations > 0,
    conv.map((c) => c.citations));
  check('confidence indicator per answer', conv.every((c, i) => c.confidence === Math.round(history[i].response.confidence * 100)),
    conv.map((c) => c.confidence));
  check('feedback buttons per answer', conv.every((c) => c.helpful));

  // Citations are collapsed; clicking one reveals its excerpt
  const firstExcerpt = history[0].response.citations[0].excerpt;
  const collapsed = await app.evaluate(`(() => {
    const d = ${panel}.querySelector('[data-role="citation"]');
    return { open: d.open, visibleText: d.innerText };
  })()`);
  check('citation starts collapsed', !collapsed.open && !collapsed.visibleText.includes(firstExcerpt.slice(0, 40)), collapsed);
  await app.evaluate(`${panel}.querySelector('[data-role="citation"] summary').click()`);
  await app.waitFor(`${panel}.querySelector('[data-role="citation"]').open`, 'citation open');
  const expanded = await app.evaluate(`${panel}.querySelector('[data-role="citation"] [data-role="excerpt"]').innerText`);
  check('expanded citation shows the excerpt', expanded.trim() === firstExcerpt.trim(), expanded.slice(0, 80));

  // Selecting a document keeps the conversation visible
  await app.evaluate(`(() => { ${DOM} $text('button', 'Refresh')[0].click(); })()`);
  await app.waitFor(`document.body.innerText.includes('Documents (3)')`, 'docs listed');
  await app.evaluate(`Array.from(document.querySelectorAll('div')).find((d) => d.innerText === 'design-notes' && d.style.fontWeight === '500').click()`);
  await app.waitFor(`document.body.innerText.includes('Filename: design-notes.md')`, 'document detail');
  check('conversation still visible with a document open', await app.evaluate(`${panel}.querySelectorAll('[data-role="exchange"]').length === 3`));
  if (shotDir) await app.screenshot(path.join(shotDir, 'conversation.png'));
  await app.close();

  // Restart: the whole conversation is back
  app = await launch(dataDir);
  await app.waitFor(`${panel}.querySelectorAll('[data-role="exchange"]').length === 3`, 'history after restart');
  const after = await app.evaluate(readConversation);
  check('full conversation restored after restart', JSON.stringify(after) === JSON.stringify(conv), after.map((c) => c.question));
  await app.close();
} catch (err) {
  check('scenario ran without errors', false, String(err));
} finally {
  fs.rmSync(dataDir, { recursive: true, force: true });
}
finish();
